def reward_coordinate_precision(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(-1.0)
            continue

        # Extract coordinates mentioned in thinking
        coords = re.findall(r'\((-?\d+\.?\d*),\s*(-?\d+\.?\d*)\)', thinking)

        score = 0.0

        # If coordinates are present, check for consistency or reasonable derivation
        # This is hard to verify without the prompt's Asymptote code.
        # Instead, reward if the model explicitly states the source of coordinates (e.g., 'from the figure', 'given')

        source_keywords = ['given', 'figure', 'diagram', 'asy', 'code', 'vertex', 'center']
        if any(k in thinking.lower() for k in source_keywords):
            score += 1.0

        # Penalize if coordinates are very large or specific without context (hallucination risk)
        for x, y in coords:
            try:
                if abs(float(x)) > 100 or abs(float(y)) > 100:
                    score -= 0.5
            except:
                pass

        # Reward if the model calculates distances or areas using these coordinates
        if re.search(r'(distance|area|length)', thinking.lower()):
            score += 1.0

        scores.append(max(-2.0, min(5.0, score)))
    return scores

def reward_polynomial_remainder_method(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(-1.0)
            continue

        # Look for polynomial remainder techniques
        keywords = ['remainder', 'division', 'mod', 'congruent', 'root', 'factor', 'cyclotomic', 'unity']

        score = 0.0
        for k in keywords:
            if k in thinking.lower():
                score += 0.5

        # Penalize if the model tries to expand high powers directly
        if 'expand' in thinking.lower() and re.search(r'\d{3,}', thinking):
            score -= 1.0

        scores.append(max(-2.0, min(5.0, score)))
    return scores

