def reward_probabilistic_reasoning(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(-1.0)
            continue

        # Look for probability-specific reasoning
        keywords = ['probability', 'independent', 'complement', 'union', 'intersection', 'sample space']

        score = 0.0
        for k in keywords:
            if k in thinking.lower():
                score += 0.5

        # Penalize if the model just multiplies probabilities without justification for independence
        if re.search(r'\d+\.\d+\s*\*', thinking) and 'independent' not in thinking.lower():
            score -= 1.0

        scores.append(max(-2.0, min(5.0, score)))
    return scores

def reward_concise_final_answer(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        solution = extract_solution(response)
        if not solution:
            scores.append(-1.0)
            continue

        # Penalize verbose answers
        if len(solution) > 50:
            score = -1.0
        elif len(solution) > 20:
            score = 0.0
        else:
            score = 2.0

        # Penalize if the answer contains explanatory text
        if re.search(r'(is|are|the|answer|equals)', solution.lower()):
            score -= 1.0

        scores.append(max(-2.0, min(5.0, score)))
    return scores
